def story_content(p):
 story=stories[p['slug']]
 paragraphs=''.join('<p>'+escape(text)+'</p>' for text in story['decisions'])
 steps=''.join('<li><h3>'+escape(step['title'])+'</h3><p>'+escape(step['text'])+'</p></li>' for step in story['steps'])
 return f"""<section class="section case-studies" aria-label="Project explanation"><article class="case-study-row"><div><p class="eyebrow">01 / The project</p><h2>What it is</h2></div><div class="case-study-copy"><p>{escape(story['overview'])}</p><p>{escape(story['audience'])}</p></div></article><article class="case-study-row"><div><p class="eyebrow">02 / The challenge</p><h2>What it needs to solve</h2></div><div class="case-study-copy"><p>{escape(story['challenge'])}</p></div></article><article class="case-study-row"><div><p class="eyebrow">03 / Design thinking</p><h2>The approach</h2></div><div class="case-study-copy">{paragraphs}</div></article><article class="case-study-row"><div><p class="eyebrow">04 / The experience</p><h2>How it works</h2></div><ol class="case-study-steps">{steps}</ol></article><div class="case-bottom"><p>{escape(story['purpose'])}</p><a class="pill" href="{p['url']}" target="_blank" rel="noopener">Visit project</a></div></section>"""
